using System.Collections.Generic;

namespace TubaWinUi3.Services;

/// <summary>
/// 教程块（教程目录 + 教程页）显示层本地化。教程内容为维护文案，显示时经 T/TSub 转换；
/// 进度键（模块_序号 / guide.Id）、Type/Action/Target/ShortcutKey 等业务键保持稳定、不参与翻译。
/// </summary>
public static class TutorialTexts
{
    private static readonly Dictionary<string, string> EnMap = new()
    {
        ["打开 PowerShell（右键开始菜单 → 终端/PowerShell），然后逐行输入以下命令：\n\n💡 安装浏览器：\n  winget install Google.Chrome\n  winget install Mozilla.Firefox\n\n💡 安装通讯工具：\n  winget install Tencent.WeChat\n  winget install Tencent.QQ\n\n💡 安装效率工具：\n  winget install Notion.Notion\n  winget install Obsidian.Obsidian\n\n💡 安装开发工具：\n  winget install Microsoft.VisualStudioCode\n  winget install Git.Git\n\n每条命令会自动下载安装，不用手动点下一步！安装完成后在开始菜单就能找到。\n\n如果命令行太麻烦，工具箱内置了 UniGetUI 包管理器，图形界面操作更直观！"] = "Open PowerShell (right-click Start → Terminal/PowerShell), then type these commands line by line:\n\n💡 Browsers:\n  winget install Google.Chrome\n  winget install Mozilla.Firefox\n\n💡 Messaging:\n  winget install Tencent.WeChat\n  winget install Tencent.QQ\n\n💡 Productivity:\n  winget install Notion.Notion\n  winget install Obsidian.Obsidian\n\n💡 Dev tools:\n  winget install Microsoft.VisualStudioCode\n  winget install Git.Git\n\nEach command downloads and installs automatically — no clicking Next! Find them in the Start menu when done.\n\nIf the command line feels like a hassle, the toolbox includes the UniGetUI package manager with a friendlier GUI!",
        ["winget 是 Windows 自带的包管理器，类似手机的应用商店，但是命令行版的。优点：干净、无捆绑、一键安装卸载、自动更新。\n\n基本用法（在 PowerShell 或终端中输入）：\n\n• 搜索软件：winget search 关键词\n  例：winget search chrome\n\n• 安装软件：winget install 软件ID\n  例：winget install Google.Chrome\n\n• 查看已装：winget list\n\n• 更新软件：winget upgrade\n\n• 卸载软件：winget uninstall 软件ID\n\n第一次用 winget 可能会问是否同意协议，输入 Y 回车即可。如果提示「winget」不是命令，需要从微软商店安装「应用安装程序」。"] = "winget is Windows' built-in package manager — like a phone app store, but on the command line. Pros: clean, bundle-free, one-command install/uninstall, auto updates.\n\nBasics (run in PowerShell or Terminal):\n\n• Search: winget search keyword\n  e.g. winget search chrome\n\n• Install: winget install AppId\n  e.g. winget install Google.Chrome\n\n• List installed: winget list\n\n• Upgrade: winget upgrade\n\n• Uninstall: winget uninstall AppId\n\nThe first run may ask you to accept the source agreement — type Y and press Enter. If it says 'winget' is not recognized, install 'App Installer' from the Microsoft Store.",
        ["三大安全渠道，按推荐顺序：\n\n① Microsoft Store（微软商店）——最安全，UWP 应用沙盒运行，自动更新，无捆绑。打开方式：开始菜单搜索「Store」或「微软商店」\n② winget —— Windows 自带包管理器，命令行一键安装，干净无捆绑，适合常用软件批量装\n③ 官网下载 —— 最灵活但需辨别真假官网，认准官网域名，远离下载站\n\n不推荐：各种软件管家、应用市场、第三方下载站，它们本身就是捆绑软件的来源！"] = "Three safe channels, in order of preference:\n\n① Microsoft Store — safest: UWP apps run sandboxed, auto-update, no bundles. Open via Start menu search.\n② winget — Windows' own package manager, one-command installs, clean and bundle-free — great for installing common apps in bulk\n③ Official websites — most flexible, but verify the real site: check the domain and stay away from download sites\n\nNot recommended: 'software butlers', app markets and third-party download sites — they ARE the source of bundleware!",
        ["推荐方式（按优先级）：\n\n① 设置卸载：Win+I 打开设置 → 应用 → 已安装的应用 → 找到软件点卸载\n② winget 卸载：winget uninstall 软件ID（命令行一键搞定）\n③ 顽固软件：用 HiBit Uninstaller 强制卸载并清理残留，工具箱里就有！\n\n注意：不要直接删除文件夹！那样注册表和启动项会残留。卸载后建议检查任务管理器→启动，关掉不需要的自启项。"] = "Recommended options (by priority):\n\n① Settings uninstall: Win+I → Apps → Installed apps → pick the app → Uninstall\n② winget: winget uninstall AppId (one command)\n③ Stubborn apps: force-uninstall and clean leftovers with HiBit Uninstaller — it's in this toolbox!\n\nNote: never just delete the folder! Registry entries and startup items would remain. After uninstalling, check Task Manager → Startup and disable what you don't need.",
        ["捆绑安装是安装一个软件时偷偷装上其他不需要的软件。识别和避免方法：\n\n① 用微软商店或 winget 安装 —— 永远不会有捆绑\n② 官网安装时选「自定义安装」—— 仔细看每一步\n③ 取消勾选「推荐安装 xxx」「设为首页」等选项\n④ 特别小心下载站的「高速下载」按钮 —— 那通常是捆绑器！点「普通下载」或「官方下载」\n⑤ 安装完成后检查桌面和开始菜单是否多了不认识的图标"] = "Bundling means an installer sneaks extra unwanted software onto your PC. How to spot and avoid it:\n\n① Install from the Microsoft Store or winget — never bundled\n② When installing from official sites, choose 'Custom install' and read every step\n③ Uncheck 'recommended extras', home-page hijacks and similar options\n④ Beware 'High-speed download' buttons on download sites — usually bundlers! Use 'Normal' or the official download instead\n⑤ After installing, check the desktop and Start menu for unknown icons",
        ["SSD 时代建议默认装 C 盘。原因：\n\n① SSD 随机读写快，装哪都一样快\n② C 盘装软件启动更快（系统盘 I/O 优先级高）\n③ 默认路径不容易出兼容性问题\n④ 只有大型游戏可以装 D 盘节省空间\n\nC 盘只要留 30GB+ 剩余空间就不会卡。如果 C 盘空间紧张，用工具箱的垃圾清理功能清理一下！"] = "With SSDs, installing to C: is fine by default:\n\n① SSDs have fast random I/O — speed is the same wherever you install\n② Apps on C: start faster (the system drive has higher I/O priority)\n③ The default path avoids compatibility issues\n④ Only large games benefit from installing to D: to save space\n\nKeep 30GB+ free on C: and it won't slow down. Short on space? Use the toolbox's junk cleaner!",
        ["内存：用 MemTest86 或 Windows 内存诊断工具（Win+R 输入 mdsched）检测，新电脑建议至少跑一遍，内存故障会导致随机蓝屏。硬盘：用 CrystalDiskInfo 查看健康状态，CrystalDiskMark 测速对比标称值。工具箱里都能找到！"] = "Memory: test with MemTest86 or the Windows Memory Diagnostic (Win+R → mdsched). Run it at least once on a new PC — faulty RAM causes random BSODs. Storage: check health with CrystalDiskInfo and compare speeds against the rated specs with CrystalDiskMark. Both are in this toolbox!",
        ["错！核心数量只是其中一个指标。CPU 性能取决于：①单核性能（影响日常流畅度）②核心数和线程数（影响多任务）③频率（越高越快）④架构代数（13 代 i5 可能比 10 代 i7 快）⑤缓存大小。选 CPU 看天梯图比看核心数靠谱——工具箱里有 CPU 天梯图！"] = "Wrong! Core count is only one factor. CPU performance depends on: ① single-core performance (daily responsiveness) ② core/thread count (multitasking) ③ clock speed (higher is faster) ④ architecture generation (a 13th-gen i5 can beat a 10th-gen i7) ⑤ cache size. Use the CPU tier list instead of counting cores — it's in this toolbox!",
        ["烤机（压力测试）是在极限负载下运行 CPU/GPU，目的是：①验证新电脑硬件是否稳定（是否有暗病）②检查散热是否合格（温度是否过高）③确认供电是否足够（是否掉电降频）④新电脑建议至少烤 15 分钟，无蓝屏死机才算通过。枕星图吧AI助手里就有烤机工具！"] = "Stress testing runs CPU/GPU at maximum load to: ① verify new hardware is stable (no hidden faults) ② check cooling is adequate (temps not too high) ③ confirm the PSU suffices (no power loss or throttling) ④ run at least 15 minutes on a new PC — passing means no BSOD or freeze. This toolbox has stress-test tools!",
        ["①打开工具箱里的 FPU 压力测试工具 ②也可以用 AIDA64 → 工具 → 系统稳定性测试，勾选 Stress FPU ③运行 15~30 分钟，观察温度和频率 ④正常温度应在 95°C 以下，频率不应大幅下降。工具箱还内置了 CPU 烤鸡功能！"] = "① Open the FPU stress tool in the toolbox ② Or use AIDA64 → Tools → System Stability Test with Stress FPU checked ③ Run 15–30 minutes, watching temps and clocks ④ Temps should stay under 95°C with no big frequency drops. The toolbox also has built-in CPU stress testing!",
        ["重点关注：①温度——CPU/GPU 不超 95°C ②频率——不应大幅降频（如 i7 从 4.5GHz 降到 2GHz 就不正常）③功耗——应接近 TDP 标称值 ④风扇转速——应随温度升高而加快。用工具箱的硬件监控功能可以实时查看这些指标！"] = "What to watch: ① Temps — CPU/GPU under 95°C ② Clocks — no big drops (an i7 falling from 4.5GHz to 2GHz is not normal) ③ Power — should approach the rated TDP ④ Fan speed — should rise with temperature. The toolbox's hardware monitor shows all of these live!",
        ["部分正确。C 盘空间不足确实会影响性能（虚拟内存和临时文件需要空间），但「满」的阈值是剩余不足 10~15GB，而不是「装了很多东西」。SSD 还需要留 10~20% 空间用于垃圾回收和磨损均衡。所以保持 C 盘有 30GB+ 剩余即可。"] = "Partly true. Low C: space does affect performance (the page file and temp files need room), but the threshold is under 10–15GB free — not 'I installed a lot of stuff'. SSDs also want 10–20% free for garbage collection and wear leveling. Keeping 30GB+ free is enough.",
        ["①检查开机自启项（任务管理器→启动），关掉不需要的 ②卸载不用的软件 ③清理临时文件（工具箱有垃圾清理工具）④检查 C 盘剩余空间（建议留 30GB+）⑤如果是机械硬盘，升级 SSD 效果最明显 ⑥重装系统是终极方案但通常不必要。"] = "① Check startup items (Task Manager → Startup) and disable unneeded ones ② Uninstall unused software ③ Clean temp files (the toolbox has a junk cleaner) ④ Check free C: space (keep 30GB+) ⑤ On an HDD, upgrading to an SSD helps most ⑥ A system reinstall is the last resort but usually unnecessary.",
        ["①用 FurMark（俗称「甜甜圈」）进行 GPU 压力测试 ②运行 15~30 分钟 ③正常温度：笔记本 90°C 以下，台式机 85°C 以下 ④如果花屏、黑屏或温度超过 95°C，说明显卡有问题。工具箱里有显卡工具分类！"] = "① Stress the GPU with FurMark ('the donut') ② Run 15–30 minutes ③ Normal temps: laptops under 90°C, desktops under 85°C ④ Artifacts, black screens or temps over 95°C point to a GPU problem. The toolbox has a GPU tools section!",
        ["①重要数据至少存两份（本地+云盘/移动硬盘）②开启 Windows 的文件历史记录功能 ③定期检查备份是否可用 ④不要把所有数据只放桌面——桌面在 C 盘，系统崩了数据就没了 ⑤OneDrive 自动同步桌面和文档，建议开启。"] = "① Keep at least two copies of important data (local + cloud/external drive) ② Enable Windows File History ③ Periodically verify your backups work ④ Don't keep everything on the desktop — it's on C:, so a system crash takes it with it ⑤ Consider enabling OneDrive to sync Desktop and Documents.",
        ["不需要。①显卡驱动建议每 1~2 个月更新一次（新游戏优化）②其他驱动「能用就不动」，更新反而可能引入问题 ③不要用第三方驱动助手（驱动精灵、驱动人生等），Windows 更新已能自动安装驱动 ④品牌机去官网下载驱动最靠谱。"] = "Not really. ① Update GPU drivers every 1–2 months (new-game optimizations) ② Other drivers: if it works, leave it — updates can introduce problems ③ Avoid third-party driver helpers (DriverGenius, Driver Life, etc.) — Windows Update installs drivers automatically ④ For brand PCs, the vendor's official site is the most reliable source.",
        ["错！现代笔记本有智能充电管理，充满后会自动切换为电源供电，不会过充。反而经常把电量用到 0% 才充电会加速电池老化。建议：日常插电使用，每月拔电用一次让电池活动活动即可。部分品牌还支持「电池保养模式」限制充到 60~80%。"] = "Wrong! Modern laptops have smart charge management: when full they switch to AC power, so there's no overcharging. In fact, running to 0% often ages the battery faster. Advice: use it plugged in daily; unplug once a month to exercise the battery. Some brands offer a 'battery care mode' capping charge at 60–80%.",
        ["大多数用户不需要分区。Windows 10/11 的文件管理和搜索已足够强大，分区反而浪费 SSD 空间（每个分区会预留备用空间）。但如果你习惯将数据与系统分开，可以分两个区。注意：C 盘建议至少留 150GB 以上空间。"] = "Most users don't need to partition. Windows 10/11 file management and search are plenty, and partitions waste SSD space (each reserves spare area). If you like keeping data separate from the system, two partitions are fine. Note: keep at least 150GB for C:.",
        ["Windows Defender 已经足够好。①它连续多年 AV-TEST 满分 ②装第三方杀毒反而可能拖慢系统 ③如果一定要额外防护，装个火绒即可——安静不弹窗 ④远离各种「安全卫士」「电脑管家」，它们本身就是流氓软件。"] = "Windows Defender is good enough. ① It has scored full marks in AV-TEST for years ② Third-party AV can actually slow the system down ③ If you must add protection, Huorong is quiet and popup-free ④ Stay away from 'security guards' and 'PC butlers' — they are the rogue software themselves.",
        ["纯 SSD 建议 1~2 个分区即可。如果是 SSD + HDD 双盘，SSD 做系统盘不分区，HDD 可按需分 2~3 个区（如 D 盘软件、E 盘数据）。分区时注意 4K 对齐（Windows 磁盘管理默认已对齐）。"] = "With a single SSD, 1–2 partitions is plenty. With SSD + HDD, leave the SSD unpartitioned as the system drive and split the HDD into 2–3 volumes as needed (e.g. D: apps, E: data). Keep 4K alignment (Windows Disk Management aligns by default).",
        ["建议开启自动更新。①安全补丁修复漏洞，防止被攻击 ②功能更新带来新特性 ③「更新会出问题」是少数情况，不更新的风险更大 ④如果担心，可以延迟更新 1~2 周等别人踩完坑。不要使用任何「关闭 Windows 更新」的工具。"] = "Keep automatic updates on. ① Patches fix vulnerabilities and prevent attacks ② Feature updates bring new capabilities ③ 'Updates break things' is rare — not updating is riskier ④ If worried, delay 1–2 weeks and let others go first. Never use 'disable Windows Update' tools.",
        ["错！注册表冗余项对性能的影响微乎其微（微软官方确认）。清理注册表反而可能删掉有用的项导致软件故障。各种「注册表清理工具」是伪需求，远离它们。真正加速的方法是清理自启项和卸载不用的软件。"] = "Wrong! Registry bloat barely affects performance (Microsoft has confirmed this). Registry cleaners can delete entries you need and break apps. 'Registry cleaning' is a fake need — avoid it. Real speedups: trim startup items and uninstall unused software.",
        ["部分正确。普通手机充电器功率太低确实不行。但现在很多轻薄本支持 USB-C PD 充电，只要充电器功率≥45W（最好 65W+）就可以充。只是高负载时可能掉电，但日常办公没问题。"] = "Partly true. Plain phone chargers are indeed too weak — but many modern thin laptops support USB-C PD charging at 45W+ (65W+ preferred). Under heavy load it may discharge, but it's fine for office work.",
        ["①跳过捆绑软件（开箱时厂商预装的可选卸载）②连接网络完成系统更新 ③安装显卡驱动 ④激活 Windows ⑤安装常用软件。枕星图吧AI助手里就能帮你完成驱动和硬件检测！"] = "① Skip bundled software (uninstall the vendor extras at first boot) ② Connect to the network and finish system updates ③ Install GPU drivers ④ Activate Windows ⑤ Install your everyday apps. This toolbox can help you with drivers and hardware checks!",
        ["错！现代电脑的睡眠模式非常成熟，睡眠状态功耗极低（约 1~2W），硬件不会因此损坏。频繁开关机反而对 SSD 和电源冲击更大。建议：日常用睡眠，一周重启一次即可。"] = "Wrong! Modern sleep is mature and draws only ~1–2W — hardware isn't damaged by it. Frequent full shutdowns stress the SSD and PSU more. Advice: sleep daily, reboot once a week.",
        ["①滚轮点击链接 = 新标签页打开 ②Ctrl+滚轮 = 缩放页面 ③双击标题栏 = 最大化/还原。建议关闭「增强指针精确度」（实际是鼠标加速，影响瞄准）。"] = "① Middle-click a link = open in a new tab ② Ctrl+wheel = zoom the page ③ Double-click the title bar = maximize/restore. Consider turning off 'Enhance pointer precision' (it's mouse acceleration and hurts aiming).",
        ["正版激活：①品牌机一般已内置数字许可证，联网自动激活 ②零售密钥在「设置→系统→激活」中输入。工具箱也提供了 KMS 激活工具，但建议优先使用正版授权。"] = "Genuine activation: ① Brand PCs usually carry a digital license and activate online automatically ② Retail keys go in Settings → System → Activation. The toolbox also offers a KMS activator, but prefer genuine licensing.",
        ["Windows 自带剪贴板历史记录功能，可以粘贴之前复制过的内容。比只能粘贴最后一次方便太多了！"] = "Windows has built-in clipboard history — paste anything you copied earlier, not just the last item. So much more convenient!",
        ["系统自带截图工具，可以截取任意区域、窗口或全屏。截图后自动复制到剪贴板，Win+V 即可粘贴。"] = "The built-in screenshot tool captures any region, window or the full screen, and copies to the clipboard automatically — paste with Win+V.",
        ["电脑卡顿时第一时间打开任务管理器，结束卡死进程。比 Ctrl+Alt+Del 更快更直接！"] = "When the PC freezes, open Task Manager first thing and kill the stuck process. Faster and more direct than Ctrl+Alt+Del!",
        ["跟着引导一步步操作，每完成一步都会获得确认反馈。像手机教程一样，亲手试过的才记得住！"] = "Follow the guide step by step — each completed step gives confirmation feedback. Like a phone tutorial: you remember what you actually did!",
        ["在浏览器、资源管理器等应用中，Ctrl+W 关闭当前标签页。比找关闭按钮快得多！"] = "In browsers, Explorer and similar apps, Ctrl+W closes the current tab. Way faster than hunting for the close button!",
        ["Windows 精密触控板支持丰富的多点手势操作，掌握它们让你的效率翻倍。"] = "Windows precision touchpads support rich multi-finger gestures. Master them and double your efficiency.",
        ["进度 {pct}%（{doneItems}/{totalItems}）"] = "Progress {pct}% ({doneItems}/{totalItems})",
        ["在打开的窗口间快速切换，按住 Alt 连续按 Tab 选择目标窗口。"] = "Switch between open windows quickly — hold Alt and tap Tab to pick a window.",
        ["一键最小化所有窗口显示桌面，再按一次恢复。找文件、看壁纸必备！"] = "Minimize everything to show the desktop; press again to restore. Essential for finding files or enjoying your wallpaper!",
        ["请按下 Ctrl + Shift + Esc 打开任务管理器"] = "Press Ctrl + Shift + Esc to open Task Manager",
        ["快速打开文件资源管理器，比从桌面找图标快多了。"] = "Open File Explorer fast — quicker than hunting for the icon on the desktop.",
        ["请按下 Win + Shift + S 截图"] = "Press Win + Shift + S to take a screenshot",
        ["「笔记本要一直插电用会伤电池」——真的吗？"] = "'Leaving a laptop plugged in damages the battery' — is it true?",
        ["「多核 CPU 一定比少核快」——真的吗？"] = "'More cores always make a CPU faster' — is it true?",
        ["请在系统设置中查看和自定义你的触控板手势"] = "Check and customize your touchpad gestures in system settings",
        ["任务管理器：Ctrl+Shift+Esc"] = "Task Manager: Ctrl+Shift+Esc",
        ["「手机充电器不能给电脑充电」——真的吗？"] = "'Phone chargers can't charge a laptop' — is it true?",
        ["请按下 Win + E 打开资源管理器"] = "Press Win + E to open File Explorer",
        ["请按下 Win + V 打开剪贴板历史"] = "Press Win + V to open clipboard history",
        ["请按下 Ctrl + W 关闭当前标签"] = "Press Ctrl + W to close the current tab",
        ["「电脑要经常关机不然会坏」——真的吗？"] = "'PCs wear out unless you shut them down often' — is it true?",
